(() => {
  'use strict';
  const D=window.DB_DATA;
  const $=(s,r=document)=>r.querySelector(s);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths={compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm4 5-2.5 5.5L8 16l2.5-5.5Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',platform:'M3 21h18M5 21V7l7-4 7 4v14M9 10h1m4 0h1M9 14h1m4 0h1M10 21v-3h4v3',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m17-1v-2a4 4 0 0 0-3-3M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m8 1a4 4 0 0 1 0 7',bookmark:'M6 3h12v18l-6-4-6 4z',collection:'M3 7h7l2 2h9v11H3zM3 7V4h7l2 3h7',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15M16 16l5 5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12h4',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',spark:'m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7Z',fire:'M13 2c1 5-3 6-3 9-2-1-3-2-3-4-6 7-4 14 5 14 8 0 12-8 1-19Z',heart:'M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-6 5 2 12 8 17 6-5 14-12 8-17Z',thumb:'M7 10 11 3c2 0 3 1 2 6h6c2 0 2 2 1 5l-2 6H7ZM3 10h4v10H3z',share:'M15 3h6v6m0-6L10 14M10 5H4v15h15v-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',sliders:'M4 5h16M4 12h16M4 19h16M8 2v6m8 1v6M10 16v6',compare:'M8 3v18m8-18v18M4 7l4-4 4 4m0 10 4 4 4-4',plus:'M12 5v14M5 12h14',shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5Zm-4 9 3 3 5-6',wifi:'M2 8c6-5 14-5 20 0M5 12c4-4 10-4 14 0M9 16c2-1 4-1 6 0m-3 4h.01',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 8v6m0-10v.01',back:'M20 12H4m6-6-6 6 6 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v5l3 2',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m-9 9h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',copy:'M8 8h13v13H8zM16 8V3H3v13h5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M9 10v7m6-7v7',logout:'M9 4H3v16h6m5-13 5 5-5 5m-7-5h14',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',play:'m8 4 13 8-13 8Z'};
  const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
  const avatar=(c,size='')=>`<span class="avatar ${size}" style="--avatar:${c.color||'#e9d0ac'}">${esc(c.initials||'AL')}</span>`;
  const rating=n=>`<span class="rating">${icon('star')}${Number(n).toFixed(1)}</span>`;
  const byGame=id=>D.games.find(x=>x.id===id);
  const byPlatform=id=>D.platforms.find(x=>x.id===id);
  const byCreator=id=>D.creators.find(x=>x.id===id)||{id:'you',name:'Alex Morgan',handle:'@alexm',initials:'AM',color:'#e9d0ac'};
  let S={savedGames:[],savedPlatforms:[],savedCollections:[],following:[],helpful:[],reviews:[],collections:[],compare:[],profile:{name:'Alex Morgan',bio:'Finding my kind of play.'}};
  let storageOK=true;
  try{const v=JSON.parse(localStorage.getItem('degenbot.v1')||'null');if(v&&typeof v==='object'){for(const k of ['savedGames','savedPlatforms','savedCollections','following','helpful','reviews','collections','compare'])if(Array.isArray(v[k]))S[k]=v[k];if(v.profile&&typeof v.profile.name==='string')S.profile=v.profile;}}catch(e){storageOK=false;}
  const persist=()=>{try{localStorage.setItem('degenbot.v1',JSON.stringify(S));}catch(e){storageOK=false;toast('Changes are saved for this session only. Browser storage is unavailable.');}};
  let toastTimer;
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
  const navs=[['discover','compass','Discover'],['games','grid','Explore slots'],['platforms','platform','Platforms'],['community','people','Community'],['collections','collection','Collections'],['saved','bookmark','Saved picks']];
  let route='discover',routeId='',category='All games',sort='popular',query='',pace='All paces',studio='All studios',communityTab='reviews',savedTab='games';
  const gameCard=g=>`<article class="game-card"><a class="art-link" href="#game/${g.id}" aria-label="Explore ${esc(g.name)}"><div class="game-art art-${g.art}">${g.tag?`<span class="art-badge">${g.tag}</span>`:''}<span class="game-art-title">${g.name}</span></div></a><button class="icon-button save-button ${S.savedGames.includes(g.id)?'active':''}" data-action="save-game" data-id="${g.id}" aria-label="${S.savedGames.includes(g.id)?'Unsave':'Save'} ${g.name}" aria-pressed="${S.savedGames.includes(g.id)}">${icon('bookmark')}</button><div class="game-info"><div class="game-title-row"><a href="#game/${g.id}"><h3>${g.name}</h3></a>${rating(g.rating)}</div><div class="game-meta"><span>${g.studio}</span><span class="review-count">${g.reviews} reviews</span></div></div></article>`;
  const platformLogo=p=>`<span class="platform-logo" style="--platform:${p.color}">${p.symbol}</span>`;
  function collectionCard(c){const author=byCreator(c.author);return `<a class="collection-card" href="#collection/${c.id}"><div class="collection-art"><div class="game-art art-${c.art}"></div><div class="collection-overlay"><span class="eyebrow">${esc(c.tag||'YOUR COLLECTION')}</span><h3>${esc(c.name)}</h3></div></div><div class="collection-info">${avatar(author)}<span>${esc(c.author==='you'?S.profile.name:author.name)}</span><span>· ${c.games.length} picks</span>${icon('bookmark')}<span>${c.saves||0}</span></div></a>`;}
  function creatorRow(c){return `<div class="creator-row"><a href="#creator/${c.id}">${avatar(c,'lg')}</a><div class="creator-details"><a href="#creator/${c.id}"><strong>${c.name}</strong></a><span>${c.focus}</span></div><button class="button small ${S.following.includes(c.id)?'subtle':''}" data-action="follow" data-id="${c.id}">${S.following.includes(c.id)?'Following':'+ Follow'}</button></div>`;}
  function reviewCard(r){const c=byCreator(r.author),target=r.type==='game'?byGame(r.target):byPlatform(r.target);return `<article class="review-card"><div class="review-head">${avatar(c)}<div><${r.author==='you'?'span':'a'} ${r.author==='you'?'':`href="#creator/${c.id}"`} class="author-name">${esc(r.author==='you'?S.profile.name:c.name)}</${r.author==='you'?'span':'a'}><small>${r.author==='you'?'Your local review':c.handle}</small></div>${rating(r.rating)}</div>${target?`<a href="#${r.type}/${target.id}" class="review-target">${target.name}</a>`:''}<h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><div class="review-actions"><button class="${S.helpful.includes(r.id)?'active':''}" data-action="helpful" data-id="${r.id}" aria-pressed="${S.helpful.includes(r.id)}">${icon('thumb')}Helpful · ${(r.helpful||0)+(S.helpful.includes(r.id)?1:0)}</button><button data-action="share" data-type="review" data-id="${r.id}" aria-label="Share review">${icon('share')}</button><span class="review-date">${esc(r.date)}</span></div></article>`;}
  function shell(){const active=['game'].includes(route)?'games':route==='platform'?'platforms':route==='collection'?'collections':route==='creator'?'community':route;$('#sidebar').innerHTML=`<a class="brand" href="#discover" aria-label="DegenBot home"><span class="brand-mark">D</span><span class="brand-word">DegenBot<span>®</span></span></a><div class="nav-label">YOUR NEXT DISCOVERY</div><nav aria-label="Main navigation">${navs.slice(0,4).map(([id,i,name])=>`<a href="#${id}" class="nav-item ${active===id?'active':''}" title="${name}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${name}</span></a>`).join('')}</nav><div class="nav-divider"></div><div class="nav-label">YOUR CORNER</div><nav aria-label="Personal navigation">${navs.slice(4).map(([id,i,name])=>`<a href="#${id}" class="nav-item ${active===id?'active':''}" title="${name}">${icon(i)}<span>${name}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="club-card">${icon('spark')}<h3>Good taste travels.</h3><p>Make a collection. Share a little of what makes you, you.</p><button class="button primary small" data-action="create-collection">Create a collection ${icon('plus')}</button></div><button class="sidebar-meta" data-action="about">${icon('shield')}Independent by design</button></div>`;
    $('#topbar').innerHTML=`<div class="mobile-brand"><a class="brand-mark" href="#discover">D</a><a class="brand-word" href="#discover">DegenBot</a></div><div class="breadcrumb">Explore <span>/</span> ${esc((navs.find(n=>n[0]===active)||['','','Your corner'])[2])}</div><form class="search-form" id="global-search">${icon('search')}<input aria-label="Search games, platforms, and creators" name="query" placeholder="Search games, platforms, people..." value="${route==='search'?esc(query):''}" autocomplete="off"><kbd>/</kbd></form><div class="topbar-end"><button class="offline-label" data-action="about">${icon('wifi')}Offline preview</button><button class="icon-button" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><a class="profile-control" href="#profile" aria-label="Your profile">${avatar({initials:S.profile.name.split(' ').map(x=>x[0]).join('').slice(0,2)})}${icon('down')}</a></div>`;
    $('#mobile-nav').innerHTML=[navs[0],navs[1],navs[2],navs[3],navs[5]].map(([id,i,name])=>`<a href="#${id}" class="${active===id?'active':''}">${icon(i)}<span>${id==='games'?'Slots':id==='saved'?'Saved':name}</span></a>`).join('');
  }
  const heading=(title,sub,extra='')=>`<div class="page-intro"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`;
  const sectionHeading=(title,link,label='View all',i='')=>`<div class="section-heading"><h2>${i?icon(i):''}${title}</h2>${link?`<a class="text-link" href="#${link}">${label} ${icon('arrow')}</a>`:''}</div>`;
  const categoryFilters=()=>`<div class="filter-row" aria-label="Game category">${['All games','Adventure','Arcade','Classic','Sci-fi'].map((c,i)=>`<button class="filter-chip ${category===c?'active':''}" data-action="category" data-value="${c}" aria-pressed="${category===c}">${i===0?icon('grid'):''}${c}</button>`).join('')}</div>`;
  function discover(){let games=D.games.filter(g=>category==='All games'||g.category===category).slice(0,4);return `${heading('Find your kind of play.<span class="welcome-mark">✳</span>','Good games. Honest opinions. People who get it.','<span class="date-label">THE DISCOVERY EDIT · VOL. 014</span>')}<div class="feature-layout"><article class="hero-feature"><img class="hero-bg" src="assets/jungle.webp" alt="A luminous jade guardian watches over a lush jungle temple"><div class="hero-copy"><span class="eyebrow">${icon('spark')} THE EDITOR’S PICK</span><h2>A little wild.<br>A lot to love.</h2><p>Meet Jade Jungle. A world worth getting lost in, picked by our community.</p><a class="button primary" href="#game/jade-jungle">Explore the game ${icon('arrow')}</a></div><div class="hero-bottom"><span class="avatars">${D.creators.map(c=>avatar(c)).join('')}</span>128 player perspectives</div></article><aside class="edit-card"><span class="eyebrow">THE SHORTLIST</span><h3>Great platforms.<br>Less guesswork.</h3>${D.platforms.slice(0,3).map((p,i)=>`<a class="rank-row" href="#platform/${p.id}"><span class="rank-number">0${i+1}</span>${platformLogo(p)}<div class="rank-info"><strong>${p.name}</strong><span>${['The all-round favorite','Details done right','For the new-release crowd'][i]}</span></div>${rating(p.rating)}</a>`).join('')}<a href="#platforms" class="text-link">Find your platform ${icon('arrow')}</a></aside></div><section class="section">${sectionHeading('On everyone’s radar','games','Explore all slots','fire')}${categoryFilters()}<div class="game-grid home-games">${games.map(gameCard).join('')}</div></section><section class="section">${sectionHeading('Good taste, collected.','collections','All collections')}<div class="collection-grid">${D.collections.map(collectionCard).join('')}</div></section><section class="section editorial-banner"><div class="banner-symbol">${icon('compass')}</div><div><h3>Your next favorite has a backstory.</h3><p>Discover the players behind the picks.</p></div><a class="button" href="#community">Meet the community ${icon('arrow')}</a></section><section class="section community-layout"><div>${sectionHeading('From the community','community','More perspectives')}${reviewCard(D.reviews[0])}</div><div>${sectionHeading('People with good taste','community','Meet all')}${D.creators.map(creatorRow).join('')}</div></section>`;}
  const allCollections=()=>[...S.collections,...D.collections];
  const allReviews=()=>[...S.reviews,...D.reviews];
  const empty=(title,body,link='games',label='Explore games',action='')=>`<div class="empty-state">${icon('compass')}<h2>${esc(title)}</h2><p>${esc(body)}</p>${action?`<button class="button primary" data-action="${action}">${label} ${icon('arrow')}</button>`:link?`<a class="button primary" href="#${link}">${label} ${icon('arrow')}</a>`:''}</div>`;
  const backLink=(to,text)=>`<a class="back-link" href="#${to}">${icon('back')}${text}</a>`;
  function filteredGames(){let rows=D.games.filter(g=>(category==='All games'||g.category===category)&&(pace==='All paces'||g.pace===pace)&&(studio==='All studios'||g.studio===studio)&&(!query||`${g.name} ${g.studio} ${g.category} ${g.theme} ${g.mechanic}`.toLowerCase().includes(query.trim().toLowerCase())));return rows.sort((a,b)=>sort==='rating'?b.rating-a.rating:sort==='newest'?b.release.localeCompare(a.release):sort==='az'?a.name.localeCompare(b.name):b.reviews-a.reviews);}
  function catalog(){const rows=filteredGames();return `${heading('The next one you’ll love.','Explore by mood, mechanic, or a name you heard in the group.','<span class="pill">12 curated games</span>')}<div class="catalog-toolbar"><div class="catalog-search">${icon('search')}<input id="catalog-search" aria-label="Search the game catalog" value="${esc(query)}" placeholder="Find a game or studio..."></div><select id="game-sort" aria-label="Sort games"><option value="popular" ${sort==='popular'?'selected':''}>Most reviewed</option><option value="rating" ${sort==='rating'?'selected':''}>Highest rated</option><option value="newest" ${sort==='newest'?'selected':''}>Newest releases</option><option value="az" ${sort==='az'?'selected':''}>Name: A–Z</option></select><button class="button" data-action="filters">${icon('sliders')}Filters${pace!=='All paces'||studio!=='All studios'?'<span class="filter-dot"></span>':''}</button></div>${categoryFilters()}<div class="results-label"><span>${rows.length} ${rows.length===1?'game':'games'}${query?` for “${esc(query)}”`:''}</span>${query||pace!=='All paces'||studio!=='All studios'||category!=='All games'?'<button class="text-link" data-action="clear-filters">Clear all filters</button>':'<span>Picked for the experience. Reviewed by people.</span>'}</div>${rows.length?`<div class="game-grid catalog-grid">${rows.map(gameCard).join('')}</div>`:empty('Nothing on this frequency.','Try a different search or clear your filters.','','')}<div class="catalog-note">${icon('info')}Game ratings describe the experience. Sample RTP values are illustrative long-run parameters, not a prediction of results.</div>`;}
  function detailReviews(type,id){const rows=allReviews().filter(r=>r.type===type&&r.target===id);return `<section class="section" id="reviews"><div class="section-heading"><div><h2>Player perspectives</h2><p>Different tastes. A better picture.</p></div><button class="button" data-action="write-review" data-type="${type}" data-id="${id}">${icon('edit')}Write a review</button></div>${rows.length?`<div class="review-grid">${rows.map(reviewCard).join('')}</div>`:empty('Be the first to share your perspective.','What stood out? What would you change? Your experience can help someone else.','','')}</section>`;}
  function gameDetail(){const g=byGame(routeId);if(!g)return notFound();return `${backLink('games','Back to all games')}<section class="detail-hero"><div class="detail-art-wrap"><div class="game-art art-${g.art} detail-art"><span class="detail-art-name">${g.name}</span></div><button class="art-expand button small" data-action="artwork" data-id="${g.id}">${icon('grid')}View artwork</button></div><div class="detail-copy"><div class="detail-tags"><span class="pill green">${g.category}</span><span class="pill">${g.pace} pace</span></div><span class="muted studio-label">${g.studio}</span><h1>${g.name}</h1><p class="detail-tagline">${g.theme}</p><div class="detail-rating">${rating(g.rating)}<span>${g.reviews} sample reviews</span><a class="text-link" href="#game/${g.id}" data-action="scroll-reviews">Read perspectives ${icon('down')}</a></div><p class="detail-description">${g.description}</p><div class="detail-actions"><button class="button primary" data-action="save-game" data-id="${g.id}">${icon(S.savedGames.includes(g.id)?'check':'bookmark')}${S.savedGames.includes(g.id)?'Saved to your picks':'Save this game'}</button><button class="button" data-action="add-to-collection" data-id="${g.id}">${icon('collection')}Add to collection</button><button class="icon-button" data-action="share" data-type="game" data-id="${g.id}" aria-label="Share ${g.name}">${icon('share')}</button></div></div></section><div class="stat-strip">${[['Mechanic',g.mechanic],['Pace',g.pace],['Volatility',g.volatility],['Illustrative RTP',g.rtp],['Released',new Date(g.release+'T00:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'})]].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><section class="section experience-layout"><div class="insight-card"><span class="eyebrow lime">THE EXPERIENCE</span><h2>What makes it worth a look</h2><ul class="check-list">${g.likes.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul><div class="tradeoff"><strong>A little perspective</strong><p>${g.tradeoff}</p></div></div><div class="insight-card"><span class="eyebrow muted">FIND IT HERE</span><h2>Platforms with ${g.name}</h2>${g.platforms.map(id=>byPlatform(id)).map(p=>`<a class="availability-row" href="#platform/${p.id}">${platformLogo(p)}<strong>${p.name}</strong>${rating(p.rating)}${icon('chevron')}</a>`).join('')}<p class="sample-note">Illustrative availability in this offline showcase.</p></div></section>${detailReviews('game',g.id)}<section class="section">${sectionHeading('A few more in your orbit','games')}<div class="game-grid">${D.games.filter(x=>x.id!==g.id).sort((a,b)=>Number(b.category===g.category)-Number(a.category===g.category)).slice(0,4).map(gameCard).join('')}</div></section>`;}
  let platformSort='rating',platformQuery='';
  function platformCard(p){return `<article class="platform-card"><div class="platform-card-head"><a href="#platform/${p.id}">${platformLogo(p)}</a><div><a href="#platform/${p.id}"><h3>${p.name}</h3></a><span>${p.reviews} sample reviews</span></div>${rating(p.rating)}</div><p>${p.tag}</p><div class="platform-card-stats"><div><small>Game library</small><strong>${p.games.toLocaleString()}+</strong></div><div><small>Mobile experience</small><strong>${p.mobile.toFixed(1)} / 5</strong></div></div><div class="platform-tags"><span>${icon('shield')}Clear account policies</span><span>${icon('people')}${p.studios} studios</span></div><div class="platform-card-actions"><a class="button" href="#platform/${p.id}">Explore platform ${icon('arrow')}</a><button class="icon-button ${S.compare.includes(p.id)?'active':''}" data-action="compare" data-id="${p.id}" aria-label="${S.compare.includes(p.id)?'Remove':'Add'} ${p.name} ${S.compare.includes(p.id)?'from':'to'} comparison" aria-pressed="${S.compare.includes(p.id)}">${icon(S.compare.includes(p.id)?'check':'compare')}</button><button class="icon-button ${S.savedPlatforms.includes(p.id)?'active':''}" data-action="save-platform" data-id="${p.id}" aria-label="Save ${p.name}" aria-pressed="${S.savedPlatforms.includes(p.id)}">${icon('bookmark')}</button></div></article>`;}
  function platforms(){let rows=D.platforms.filter(p=>`${p.name} ${p.tag}`.toLowerCase().includes(platformQuery.trim().toLowerCase()));rows.sort((a,b)=>platformSort==='library'?b.games-a.games:platformSort==='mobile'?b.mobile-a.mobile:b.rating-a.rating);return `${heading('Find a place that fits.','Compare the experience, understand the details, and make your own shortlist.')}<div class="platform-intro-banner"><div>${icon('shield')}<span>Independent perspectives. Clear tradeoffs.</span></div><button class="text-link" data-action="methodology">How we review ${icon('arrow')}</button></div><div class="catalog-toolbar"><div class="catalog-search">${icon('search')}<input id="platform-search" aria-label="Search platforms" value="${esc(platformQuery)}" placeholder="Find a platform..."></div><select id="platform-sort" aria-label="Sort platforms"><option value="rating" ${platformSort==='rating'?'selected':''}>Community rating</option><option value="library" ${platformSort==='library'?'selected':''}>Largest library</option><option value="mobile" ${platformSort==='mobile'?'selected':''}>Mobile experience</option></select><a class="button" href="#compare">${icon('compare')}Compare ${S.compare.length?`(${S.compare.length})`:''}</a></div><div class="results-label"><span>${rows.length} curated platforms</span><span>Select up to 3 to compare side by side</span></div>${rows.length?`<div class="platform-grid">${rows.map(platformCard).join('')}</div>`:empty('No platforms found.','Try a different platform name.','','View all platforms','clear-platform-search')}<p class="catalog-note">${icon('info')}All platform names, ratings, and service details are fictional demonstration data.</p>`;}
  function platformDetail(){const p=byPlatform(routeId);if(!p)return notFound();return `${backLink('platforms','Back to all platforms')}<section class="platform-profile"><div class="platform-profile-title"><span class="platform-logo large" style="--platform:${p.color}">${p.symbol}</span><div><span class="eyebrow muted">PLATFORM PROFILE</span><h1>${p.name}</h1><p>${p.tag}</p></div><div class="platform-score">${rating(p.rating)}<span>${p.reviews} sample reviews</span></div></div><p class="platform-description">${p.description}</p><div class="detail-actions"><button class="button primary" data-action="compare" data-id="${p.id}">${icon(S.compare.includes(p.id)?'check':'compare')}${S.compare.includes(p.id)?'Added to comparison':'Add to comparison'}</button><button class="button" data-action="save-platform" data-id="${p.id}">${icon(S.savedPlatforms.includes(p.id)?'check':'bookmark')}${S.savedPlatforms.includes(p.id)?'Saved platform':'Save platform'}</button><button class="icon-button" data-action="share" data-type="platform" data-id="${p.id}" aria-label="Share platform">${icon('share')}</button><span class="sample-note">Sample profile · Updated ${p.updated}</span></div></section><section class="section experience-layout"><div class="insight-card"><h2>The experience, broken down</h2><div class="score-bars">${[['Mobile experience',p.mobile],['Customer support',p.service],['Game variety',p.variety],['Policy clarity',p.clarity]].map(([label,n])=>`<div><span>${label}</span><div class="score-track"><span style="width:${n*20}%"></span></div><strong>${n.toFixed(1)}</strong></div>`).join('')}</div><button class="text-link lime" data-action="methodology">How to read these ratings ${icon('arrow')}</button></div><div class="insight-card"><h2>The details that matter</h2><dl class="facts-list">${[['Identity verification',p.kyc],['Customer support',p.support],['Illustrative withdrawal time',p.withdrawal],['Minimum withdrawal',p.minimum],['Withdrawal fee',p.fee],['Game studios',p.studios]].map(([l,v])=>`<div><dt>${l}</dt><dd>${v}</dd></div>`).join('')}</dl></div></section><section class="section two-col"><div class="insight-card"><span class="eyebrow lime">WHAT STANDS OUT</span><ul class="check-list">${p.strengths.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul></div><div class="insight-card"><span class="eyebrow muted">BEFORE YOU DECIDE</span><p class="body-copy">${p.consideration}</p><p class="sample-note">Service details are illustrative and are not verified real-world claims.</p></div></section><section class="section">${sectionHeading(`Discover on ${p.name}`,'games')}<div class="game-grid">${D.games.filter(g=>g.platforms.includes(p.id)).slice(0,4).map(gameCard).join('')}</div></section>${detailReviews('platform',p.id)}`;}
  function comparison(){const rows=S.compare.map(byPlatform).filter(Boolean);return `${backLink('platforms','Back to platforms')}${heading('A clearer side-by-side.','The details that make a difference, all in one place.',rows.length?'<button class="button" data-action="clear-compare">Clear comparison</button>':'')}<div class="compare-picker">${D.platforms.map(p=>`<button class="filter-chip ${S.compare.includes(p.id)?'active':''}" data-action="compare" data-id="${p.id}" aria-pressed="${S.compare.includes(p.id)}">${icon(S.compare.includes(p.id)?'check':'plus')}${p.name}</button>`).join('')}<span class="sample-note">Choose up to 3</span></div>${rows.length?`<div class="table-scroll"><table class="compare-table"><caption class="sr-only">Platform comparison using fictional sample data</caption><thead><tr><th scope="col">At a glance</th>${rows.map(p=>`<th scope="col"><div>${platformLogo(p)}<a href="#platform/${p.id}">${p.name}</a><button class="icon-button" data-action="compare" data-id="${p.id}" aria-label="Remove ${p.name}">${icon('close')}</button></div></th>`).join('')}</tr></thead><tbody>${[['Community rating',p=>rating(p.rating)],['Best for',p=>p.tag],['Game library',p=>`${p.games.toLocaleString()}+ games`],['Studios',p=>p.studios],['Mobile experience',p=>`${p.mobile.toFixed(1)} / 5`],['Customer support',p=>p.support],['Support response',p=>p.response],['Identity verification',p=>p.kyc],['Withdrawal time',p=>p.withdrawal],['Minimum withdrawal',p=>p.minimum],['Fees',p=>p.fee],['Worth knowing',p=>p.consideration]].map(([label,fn])=>`<tr><th scope="row">${label}</th>${rows.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="catalog-note">${icon('info')}All comparison figures are sample data. Ratings describe different aspects of the experience and do not guarantee service or outcomes.</div>`:empty('Your shortlist starts here.','Select two or three platforms above to see how their experiences compare.','','')}`;}
  function collections(){return `${heading('Good taste deserves a home.','Player-made edits, personal favorites, and rabbit holes worth exploring.','<button class="button primary" data-action="create-collection">'+icon('plus')+'Create a collection</button>')}${S.collections.length?`<section class="section">${sectionHeading('Made by you')}<div class="collection-grid">${S.collections.map(collectionCard).join('')}</div></section>`:''}<section class="section">${sectionHeading('The community edit')}<div class="collection-grid">${D.collections.map(collectionCard).join('')}</div></section><section class="section editorial-banner"><div class="banner-symbol">${icon('collection')}</div><div><h3>What’s your kind of play?</h3><p>Put a few favorites together. Tell us why they belong.</p></div><button class="button" data-action="create-collection">Make your first edit ${icon('plus')}</button></section>`;}
  function collectionDetail(){const c=allCollections().find(x=>x.id===routeId);if(!c)return notFound();const author=byCreator(c.author),own=c.author==='you';return `${backLink('collections','Back to collections')}<div class="collection-detail-hero"><div class="game-art art-${c.art}"></div><div class="collection-detail-copy"><span class="eyebrow">${esc(c.tag||'YOUR PERSONAL EDIT')}</span><h1>${esc(c.name)}</h1><p>${esc(c.subtitle)}</p><div class="collection-byline">${avatar(author)}<span>Curated by ${esc(own?S.profile.name:author.name)}</span><span>· ${c.games.length} picks</span></div></div></div><div class="collection-detail-actions"><button class="button primary" data-action="share" data-type="collection" data-id="${c.id}">${icon('share')}Share this collection</button>${own?`<button class="button" data-action="edit-collection" data-id="${c.id}">${icon('edit')}Edit collection</button><button class="icon-button" data-action="delete-collection" data-id="${c.id}" aria-label="Delete collection">${icon('trash')}</button>`:`<button class="button" data-action="save-collection" data-id="${c.id}">${icon(S.savedCollections.includes(c.id)?'check':'bookmark')}${S.savedCollections.includes(c.id)?'Collection saved':'Save collection'}</button>`}</div><section class="section">${c.games.length?`<div class="game-grid">${c.games.map(byGame).filter(Boolean).map(gameCard).join('')}</div>`:empty('A little room for discovery.','Add games to make this collection your own.','games','Find your first pick')}</section>`;}
  function community(){const rows=communityTab==='following'?allReviews().filter(r=>S.following.includes(r.author)):allReviews();return `${heading('Find your people.','Good recommendations start with knowing who they come from.','<button class="button primary" data-action="write-review">'+icon('edit')+'Share a perspective</button>')}<div class="community-feature"><span class="eyebrow lime">THE PEOPLE BEHIND THE PICKS</span><h2>Different players.<br>A shared curiosity.</h2><p>Follow a point of view, discover a new favorite, and leave a little of your own experience behind.</p><div class="community-avatars">${D.creators.map(c=>avatar(c,'xl')).join('')}</div></div><div class="community-layout"><section><div class="tab-bar"><button data-action="community-tab" data-value="reviews" class="${communityTab==='reviews'?'active':''}">All perspectives</button><button data-action="community-tab" data-value="following" class="${communityTab==='following'?'active':''}">Following ${S.following.length?`(${S.following.length})`:''}</button></div><div class="review-stack">${rows.length?rows.map(reviewCard).join(''):empty('Your circle is taking shape.','Follow a creator to see their perspectives here.','','')}</div></section><aside><div class="section-heading"><h2>Worth a follow</h2></div>${D.creators.map(creatorRow).join('')}<div class="community-guidelines"><span class="eyebrow lime">A BETTER CONVERSATION</span><h3>Specific is helpful.</h3><p>Tell us what worked, what didn’t, and who might enjoy it. A thoughtful tradeoff is worth more than a perfect score.</p><button class="text-link" data-action="guidelines">Our community guidelines ${icon('arrow')}</button></div></aside></div>`;}
  function creatorDetail(){const c=D.creators.find(x=>x.id===routeId);if(!c)return notFound();return `${backLink('community','Back to the community')}<div class="creator-profile">${avatar(c,'xl')}<div><span class="eyebrow lime">COMMUNITY CURATOR</span><h1>${c.name}</h1><p>${c.handle} · ${c.role}</p></div><button class="button primary" data-action="follow" data-id="${c.id}">${icon(S.following.includes(c.id)?'check':'plus')}${S.following.includes(c.id)?'Following':'Follow creator'}</button></div><p class="creator-bio">${c.bio}</p><div class="profile-stats"><div><strong>${(c.followers+(S.following.includes(c.id)?1:0)).toLocaleString()}</strong><span>Sample followers</span></div><div><strong>${c.reviews}</strong><span>Sample perspectives</span></div><div><strong>${c.focus}</strong><span>Comes for the</span></div></div>${D.collections.filter(x=>x.author===c.id).length?`<section class="section">${sectionHeading('Curated by '+c.name.split(' ')[0])}<div class="collection-grid">${D.collections.filter(x=>x.author===c.id).map(collectionCard).join('')}</div></section>`:''}<section class="section">${sectionHeading('Recent perspectives')}<div class="review-grid">${D.reviews.filter(x=>x.author===c.id).map(reviewCard).join('')}</div></section>`;}
  function saved(){const gs=S.savedGames.map(byGame).filter(Boolean),ps=S.savedPlatforms.map(byPlatform).filter(Boolean),cs=S.savedCollections.map(id=>allCollections().find(c=>c.id===id)).filter(Boolean);return `${heading('Your kind of good.','The games, places, and collections you want to come back to.','<a class="button" href="#collections">'+icon('collection')+'Your collections</a>')}<div class="tab-bar">${[['games','Games',gs],['platforms','Platforms',ps],['collections','Collections',cs]].map(([key,label,rows])=>`<button data-action="saved-tab" data-value="${key}" class="${savedTab===key?'active':''}">${label}<span>${rows.length}</span></button>`).join('')}</div>${savedTab==='games'?(gs.length?`<div class="game-grid">${gs.map(gameCard).join('')}</div>`:empty('A good find deserves a bookmark.','Save a game and it will be right here when you return.')):savedTab==='platforms'?(ps.length?`<div class="platform-grid">${ps.map(platformCard).join('')}</div>`:empty('Start your personal shortlist.','Save platforms to keep their details close at hand.','platforms','Explore platforms')):(cs.length?`<div class="collection-grid">${cs.map(collectionCard).join('')}</div>`:empty('Keep a little inspiration.','Save a community collection to revisit its picks.','collections','Explore collections'))}`;}
  function searchPage(){const q=query.trim().toLowerCase(),games=D.games.filter(g=>`${g.name} ${g.studio} ${g.category}`.toLowerCase().includes(q)),platforms=D.platforms.filter(p=>`${p.name} ${p.tag}`.toLowerCase().includes(q)),creators=D.creators.filter(c=>`${c.name} ${c.handle} ${c.focus}`.toLowerCase().includes(q));return `${heading(q?`Results for “${esc(query)}”`:'A little curiosity goes a long way.',q?`${games.length+platforms.length+creators.length} matches across DegenBot`:'Search for a game, platform, studio, or person.')}${!q?empty('What caught your attention?','Use the search at the top to find it.','',''):games.length+platforms.length+creators.length===0?empty('No matches found.','Try a different spelling, a studio name, or a broader search.'):''}${q&&games.length?`<section class="section">${sectionHeading('Games')}<div class="game-grid">${games.map(gameCard).join('')}</div></section>`:''}${q&&platforms.length?`<section class="section">${sectionHeading('Platforms')}<div class="platform-grid">${platforms.map(platformCard).join('')}</div></section>`:''}${q&&creators.length?`<section class="section">${sectionHeading('People')}<div class="creator-search-grid">${creators.map(creatorRow).join('')}</div></section>`:''}`;}
  function profile(){return `${heading('Your corner of DegenBot.','A little about you. A lot about what you like.','<button class="button" data-action="edit-profile">'+icon('edit')+'Edit profile</button>')}<div class="creator-profile">${avatar({initials:S.profile.name.split(' ').map(s=>s[0]).join('').slice(0,2)},'xl')}<div><span class="eyebrow lime">COMMUNITY MEMBER</span><h1>${esc(S.profile.name)}</h1><p>${esc(S.profile.bio)}</p></div><span class="pill">Local profile</span></div><div class="profile-stats"><div><strong>${S.savedGames.length+S.savedPlatforms.length}</strong><span>Saved picks</span></div><div><strong>${S.collections.length}</strong><span>Collections</span></div><div><strong>${S.reviews.length}</strong><span>Perspectives</span></div><div><strong>${S.following.length}</strong><span>Following</span></div></div><section class="section">${sectionHeading('Your collections','collections','View all')}${S.collections.length?`<div class="collection-grid">${S.collections.map(collectionCard).join('')}</div>`:empty('Make a little room for your taste.','Bring a few games together in your first collection.','collections','Create your first collection')}</section><section class="section">${sectionHeading('Your perspectives')}${S.reviews.length?`<div class="review-grid">${S.reviews.map(reviewCard).join('')}</div>`:empty('Every perspective starts somewhere.','Write a review on a game or platform you’ve explored.','games','Find a game')}</section><div class="local-settings"><div>${icon('shield')}<span>${storageOK?'Your changes stay on this device. No account or connection needed.':'Browser storage is unavailable. Changes will last for this session only.'}</span></div><button class="text-link" data-action="export-data">Export my data</button><button class="text-link" data-action="reset-data">Reset local data</button></div>`;}
  function notFound(){return empty('This page wandered off.','Find your way back to a fresh discovery.','discover','Back to Discover');}
  function renderDock(){const el=$('#compare-dock');el.innerHTML=S.compare.length&&route!=='compare'?`<div class="compare-dock"><span>${icon('compare')}<strong>${S.compare.length} platform${S.compare.length>1?'s':''}</strong><span class="dock-label">in your shortlist</span></span><a class="button primary small" href="#compare">Compare ${icon('arrow')}</a><button class="icon-button" data-action="clear-compare" aria-label="Clear comparison">${icon('close')}</button></div>`:'';document.body.classList.toggle('has-compare',!!el.innerHTML);}
  function render(){const parts=location.hash.slice(1).split('/');route=parts[0]||'discover';try{routeId=decodeURIComponent(parts[1]||'');}catch{routeId='';}shell();const views={discover,games:catalog,game:gameDetail,platforms,platform:platformDetail,compare:comparison,collections,collection:collectionDetail,community,creator:creatorDetail,saved,search:searchPage,profile};$('#main').innerHTML=(views[route]||notFound)();renderDock();document.title=`${route==='game'?(byGame(routeId)?.name||'Discover'):route==='platform'?(byPlatform(routeId)?.name||'Platforms'):route==='discover'?'Find your kind of play':(navs.find(n=>n[0]===route)||['','','Your corner'])[2]} — DegenBot`;}
  function refreshKeepFocus(){const a=document.activeElement;const action=a?.dataset?.action,id=a?.dataset?.id,value=a?.dataset?.value;const elementId=a?.id;const pos=window.scrollY;render();if(elementId){document.getElementById(elementId)?.focus({preventScroll:true});}else if(action){const next=[...document.querySelectorAll('[data-action]')].find(x=>x.dataset.action===action&&x.dataset.id===id&&x.dataset.value===value);next?.focus({preventScroll:true});}window.scrollTo(0,pos);}
  function toggle(key,id){S[key]=S[key].includes(id)?S[key].filter(x=>x!==id):[...S[key],id];persist();refreshKeepFocus();return S[key].includes(id);}
  function toggleCompare(id){if(!byPlatform(id))return false;if(!S.compare.includes(id)&&S.compare.length>=3){toast('Compare up to 3 platforms. Remove one to make room.');return false;}toggle('compare',id);return true;}
  let modalTrigger=null,sharePayload=null;
  function openModal(title,body,wide=false){const m=$('#modal');if(!m.open)modalTrigger=document.activeElement;m.className=wide?'wide':'';m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal();document.body.classList.add('modal-open');}
  function closeModal(){const m=$('#modal');m.close();document.body.classList.remove('modal-open');if(modalTrigger?.isConnected)modalTrigger.focus({preventScroll:true});}
  $('#modal').addEventListener('cancel',()=>document.body.classList.remove('modal-open'));
  $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=$('#modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
  function createCollection(id='',gameId=''){const c=S.collections.find(x=>x.id===id);openModal(c?'Edit your collection':'Make it your kind of collection',`<form id="collection-form" data-id="${id}"><p class="modal-intro">Bring a few games together. Give them a point of view.</p><label>Collection name<input name="name" required maxlength="60" placeholder="e.g. Games for the night shift" value="${esc(c?.name||'')}"></label><label>A little context<textarea name="subtitle" maxlength="220" rows="2" placeholder="What makes these picks belong together?">${esc(c?.subtitle||'')}</textarea></label><fieldset class="game-picker"><legend>Choose your picks <span>Select at least one</span></legend>${D.games.map(g=>`<label class="game-choice"><input type="checkbox" name="games" value="${g.id}" ${(c?.games||[gameId]).includes(g.id)?'checked':''}><span class="choice-art game-art art-${g.art}"></span><span><strong>${g.name}</strong><small>${g.studio}</small></span></label>`).join('')}</fieldset><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">${c?'Save changes':'Create collection'} ${icon('arrow')}</button></div></form>`,true);}
  function reviewForm(type='',id=''){const opts=[...D.games.map(g=>({key:'game:'+g.id,name:g.name})),...D.platforms.map(p=>({key:'platform:'+p.id,name:p.name+' · Platform'}))];openModal('Share your perspective',`<form id="review-form"><p class="modal-intro">What worked, what didn’t, and who might enjoy it. Your review is saved on this device.</p><label>Your pick<select name="target" required><option value="">Choose a game or platform</option>${opts.map(x=>`<option value="${x.key}" ${x.key===type+':'+id?'selected':''}>${x.name}</option>`).join('')}</select></label><fieldset class="rating-input"><legend>Your experience</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required><span title="${n} star${n>1?'s':''}">${icon('star')}<small>${n}</small></span></label>`).join('')}</fieldset><label>A short headline<input name="title" minlength="5" maxlength="90" required placeholder="What stood out to you?"></label><label>Your review<textarea name="body" minlength="20" maxlength="1800" required placeholder="Be specific. A few thoughtful details go a long way."></textarea></label><p class="sample-note">20–1,800 characters. Focus on the experience, not predictions of winnings.</p><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Publish local review ${icon('arrow')}</button></div></form>`);}
  function share(type,id){let obj,title,desc,art=null;if(type==='game'){obj=byGame(id);if(!obj)return;title=obj.name;desc=`${obj.theme} · ${obj.studio}\n${obj.rating.toFixed(1)} / 5 sample community rating`;art=obj.art;}else if(type==='platform'){obj=byPlatform(id);if(!obj)return;title=obj.name;desc=obj.tag;}else if(type==='collection'){obj=allCollections().find(c=>c.id===id);if(!obj)return;title=obj.name;desc=`${obj.subtitle}\n${obj.games.map(g=>byGame(g)?.name).filter(Boolean).join(' · ')}`;art=obj.art;}else{obj=allReviews().find(r=>r.id===id);if(!obj)return;title=obj.title;desc=obj.body;}sharePayload={title,desc,type,id};openModal('Good taste travels.',`<p class="modal-intro">A preview of how your pick can travel in Telegram. Copy the summary or save a share card.</p><div class="telegram-preview"><div class="telegram-top">${icon('share')}MESSAGE PREVIEW</div><div class="telegram-bubble">${art!==null?`<div class="game-art art-${art} share-art"></div>`:''}<div class="telegram-content"><span class="eyebrow lime">DEGENBOT · ${type==='collection'?'THE COMMUNITY EDIT':'A GOOD FIND'}</span><h3>${esc(title)}</h3><p>${esc(desc)}</p><span class="telegram-brand">Discover your kind of play.</span></div><a href="#${type==='review'?'community':type+'/'+id}" data-action="close-modal" class="telegram-cta">Explore in DegenBot ${icon('arrow')}</a></div><small>Illustrative Telegram card · No message will be sent.</small></div><label class="share-text-label">Your share text<textarea id="share-text" readonly>${esc(title+' — DegenBot\n'+desc+'\nOffline showcase · Fictional sample content')}</textarea></label><div class="form-actions"><button class="button" data-action="download-card">${icon('download')}Save card</button><button class="button primary" data-action="copy-share">${icon('copy')}Copy summary</button></div>`);}
  function download(name,body,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  async function copyText(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return true;}}catch{}const el=document.createElement('textarea');el.value=text;el.style.cssText='position:fixed;top:0;left:0;opacity:0;';($('#modal').open?$('#modal'):document.body).appendChild(el);el.select();let ok=false;try{ok=document.execCommand('copy');}catch{}el.remove();return ok;}
  function downloadShareCard(){if(!sharePayload)return;const {title,desc}=sharePayload;const wrap=(txt,max)=>{let lines=[],line='';for(const word of txt.split(/\s+/)){if((line+' '+word).trim().length>max&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}if(line)lines.push(line);return lines;};const titleLines=wrap(title,27).slice(0,3),bodyLines=wrap(desc,62).slice(0,5);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080"><rect width="1080" height="1080" rx="44" fill="#131913"/><rect x="64" y="64" width="76" height="76" rx="21" fill="#c6ff62"/><text x="83" y="120" font-family="Arial,sans-serif" font-size="56" font-weight="800" fill="#142012">D</text><text x="160" y="119" font-family="Arial,sans-serif" font-size="47" font-weight="700" fill="#f1f3ed">DegenBot</text><text x="70" y="256" font-family="Arial,sans-serif" font-size="22" letter-spacing="5" fill="#c6ff62">GOOD TASTE. SHARED.</text>${titleLines.map((t,i)=>`<text x="64" y="${355+i*88}" font-family="Arial,sans-serif" font-size="74" font-weight="700" fill="#f1f3ed">${esc(t)}</text>`).join('')}${bodyLines.map((t,i)=>`<text x="70" y="${420+titleLines.length*88+i*38}" font-family="Arial,sans-serif" font-size="27" fill="#b2bdae">${esc(t)}</text>`).join('')}<path d="M70 884h940" stroke="#3a4537"/><text x="70" y="950" font-family="Arial,sans-serif" font-size="24" fill="#c6ff62">Find your kind of play.</text><text x="70" y="1006" font-family="Arial,sans-serif" font-size="18" fill="#8f9e89">OFFLINE SHOWCASE · FICTIONAL SAMPLE CONTENT · 18+</text></svg>`;download('DegenBot-'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.svg',svg,'image/svg+xml');toast('Your share card is ready to save.');}
  function infoModal(kind){const content={about:['Made to explore.',`<div class="about-brand"><span class="brand-mark">D</span><span class="brand-word">DegenBot</span></div><p>A home for game discovery, thoughtful platform comparisons, and people with a point of view.</p><h3>About this offline showcase</h3><p>All games, platforms, creators, reviews, ratings, and service figures are fictional sample content. The original artwork was created for this demonstration.</p><h3>Yours, on this device</h3><p>Saved picks, follows, collections, and reviews stay in this browser. Sharing creates a local card or copied text. There are no live accounts, messages, deposits, or wagers.</p><p class="sample-note">Designed for an adult audience, 18+. Demo version 1.0.</p>`],methodology:['A rating should tell you something.',`<p>Our product separates game experience from platform service, so each score has a clear purpose.</p><h3>Games: how it feels to play</h3><p>Art direction, sound, clarity, pace, mobile usability, and the quality of the mechanics. A review should explain what stood out and what could be better.</p><h3>Platforms: how the service works</h3><p>Mobile experience, customer support, game variety, and policy clarity. Service evidence should include a date and verification status.</p><h3>Context comes with the score</h3><p>Show the review count and the underlying perspectives. Commercial relationships should be disclosed, and paid placement should never change community ratings.</p><p class="sample-note">This showcase illustrates the framework. Its ratings and service claims are fictional, with no independent verification implied.</p>`],guidelines:['A better kind of conversation.',`<h3>Share your own perspective</h3><p>Tell people what you experienced. Be specific about the game, device, timing, and details that shaped your opinion.</p><h3>Make room for different tastes</h3><p>A game can be beautifully made and still not be for you. Explain who might enjoy it and give useful context.</p><h3>Keep the community useful</h3><p>No personal attacks, spam, promises of winnings, or undisclosed paid recommendations. Never post private account or payment information.</p><h3>Be clear about the evidence</h3><p>A personal experience is one perspective. Separate it from verified facts and leave space for corrections.</p>`],notifications:['You’re all caught up.',`<div class="notification-illustration">${icon('bell')}</div><h3>A quieter corner of the internet.</h3><p>In the connected product, updates from followed creators and saved collections would appear here.</p><p class="sample-note">This offline version does not receive notifications. Your follows and saved picks work locally.</p><a class="button primary" href="#community" data-action="close-modal">Find people to follow ${icon('arrow')}</a>`]};const [title,body]=content[kind]||content.about;openModal(title,`<div class="prose">${body}</div>`);}
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,type=b.dataset.type;switch(a){
    case 'category':category=b.dataset.value;refreshKeepFocus();break;
    case 'save-game':if(byGame(id))toast(toggle('savedGames',id)?'Added to your saved picks.':'Removed from your saved picks.');break;
    case 'save-platform':if(byPlatform(id))toast(toggle('savedPlatforms',id)?'Platform saved to your shortlist.':'Platform removed from saved picks.');break;
    case 'save-collection':toast(toggle('savedCollections',id)?'Collection saved. A little inspiration, kept.':'Collection removed from saved picks.');break;
    case 'follow':if(D.creators.some(c=>c.id===id))toast(toggle('following',id)?`You’re now following ${byCreator(id).name}.`:'Creator unfollowed.');break;
    case 'helpful':toggle('helpful',id);break;
    case 'compare':toggleCompare(id);break;
    case 'clear-compare':S.compare=[];persist();refreshKeepFocus();toast('Comparison cleared.');break;
    case 'clear-platform-search':platformQuery='';refreshKeepFocus();break;
    case 'clear-filters':category='All games';query='';pace='All paces';studio='All studios';refreshKeepFocus();break;
    case 'filters':openModal('Find your kind of game.',`<form id="filter-form"><label>Experience pace<select name="pace">${['All paces','Relaxed','Measured','Fast'].map(p=>`<option ${pace===p?'selected':''}>${p}</option>`).join('')}</select></label><label>Game studio<select name="studio">${['All studios',...new Set(D.games.map(g=>g.studio))].map(p=>`<option ${studio===p?'selected':''}>${p}</option>`).join('')}</select></label><p class="modal-intro">Filters combine with your search and selected category.</p><div class="form-actions"><button type="button" class="button" data-action="reset-modal-filters">Reset</button><button class="button primary" type="submit">Show games ${icon('arrow')}</button></div></form>`);break;
    case 'reset-modal-filters':$('#filter-form [name="pace"]').value='All paces';$('#filter-form [name="studio"]').value='All studios';break;
    case 'community-tab':communityTab=b.dataset.value;refreshKeepFocus();break;
    case 'saved-tab':savedTab=b.dataset.value;refreshKeepFocus();break;
    case 'create-collection':createCollection();break;
    case 'edit-collection':createCollection(id);break;
    case 'add-to-collection':if(!S.collections.length){createCollection('',id);break;}openModal('A home for this pick.',`<p class="modal-intro">Choose a collection for ${esc(byGame(id)?.name)}.</p><div class="add-collection-list">${S.collections.map(c=>`<button class="collection-select" data-action="choose-collection" data-id="${c.id}" data-game="${id}">${icon('collection')}<span><strong>${esc(c.name)}</strong><small>${c.games.length} games</small></span>${icon(c.games.includes(id)?'check':'plus')}</button>`).join('')}</div><button class="button primary" data-action="new-collection-with-game" data-id="${id}">${icon('plus')}Create a new collection</button>`);break;
    case 'new-collection-with-game':createCollection('',id);break;
    case 'choose-collection':{const c=S.collections.find(c=>c.id===id);if(!c)break;if(c.games.includes(b.dataset.game)){toast('This game is already in the collection.');break;}c.games.push(b.dataset.game);persist();closeModal();refreshKeepFocus();toast('Game added to '+c.name+'.');break;}
    case 'delete-collection':openModal('Delete this collection?',`<p class="modal-intro">This removes the collection from this device. Your saved games will still be there.</p><div class="form-actions"><button class="button" data-action="close-modal">Keep collection</button><button class="button danger" data-action="confirm-delete-collection" data-id="${id}">Delete collection</button></div>`);break;
    case 'confirm-delete-collection':S.collections=S.collections.filter(c=>c.id!==id);S.savedCollections=S.savedCollections.filter(x=>x!==id);persist();closeModal();location.hash='collections';toast('Collection deleted.');break;
    case 'write-review':reviewForm(type,id);break;
    case 'scroll-reviews':e.preventDefault();$('#reviews')?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;
    case 'artwork':{const g=byGame(id);if(g)openModal(g.name,`<div class="game-art art-${g.art} artwork-preview"></div><p class="sample-note">Original concept artwork created for the DegenBot showcase.</p>`,true);break;}
    case 'share':share(type,id);break;
    case 'copy-share':{const el=$('#share-text');const ok=await copyText(el.value);if(ok)toast('Summary copied. Ready to share.');else{el.focus();el.select();toast('Select and copy the text below. Clipboard access is unavailable.');}break;}
    case 'download-card':downloadShareCard();break;
    case 'close-modal':closeModal();break;
    case 'about':case 'methodology':case 'guidelines':case 'notifications':infoModal(a);break;
    case 'edit-profile':openModal('A little about you.',`<form id="profile-form"><label>Display name<input name="name" value="${esc(S.profile.name)}" required minlength="2" maxlength="40"></label><label>Your point of view<textarea name="bio" maxlength="160">${esc(S.profile.bio)}</textarea></label><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Save profile</button></div></form>`);break;
    case 'export-data':download('DegenBot-my-data.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),...S},null,2),'application/json');toast('Your local data is ready to save.');break;
    case 'reset-data':openModal('Start with a clean slate?',`<p class="modal-intro">This deletes your local saved picks, follows, collections, reviews, and profile edits. Sample community content stays available.</p><div class="form-actions"><button class="button" data-action="close-modal">Keep my data</button><button class="button danger" data-action="confirm-reset">Reset local data</button></div>`);break;
    case 'confirm-reset':S={savedGames:[],savedPlatforms:[],savedCollections:[],following:[],helpful:[],reviews:[],collections:[],compare:[],profile:{name:'Alex Morgan',bio:'Finding my kind of play.'}};persist();closeModal();render();toast('Local data reset. A fresh start.');break;
  }});
  document.addEventListener('submit',e=>{const f=e.target;if(!['global-search','filter-form','collection-form','review-form','profile-form'].includes(f.id))return;e.preventDefault();const fd=new FormData(f);if(f.id==='global-search'){query=String(fd.get('query')||'').trim().slice(0,150);if(route==='search'){render();window.scrollTo(0,0);}else location.hash='search';}
    if(f.id==='filter-form'){pace=fd.get('pace');studio=fd.get('studio');closeModal();render();}
    if(f.id==='collection-form'){const name=String(fd.get('name')||'').trim(),subtitle=String(fd.get('subtitle')||'').trim(),games=[...new Set(fd.getAll('games'))].filter(id=>byGame(id));if(name.length<3||name.length>60){$('.form-error',f).textContent='Give your collection a name between 3 and 60 characters.';return;}if(!games.length){$('.form-error',f).textContent='Choose at least one game for your collection.';return;}const id=f.dataset.id||'local-'+Date.now().toString(36),existing=S.collections.find(c=>c.id===id),obj={id,name,subtitle:subtitle.slice(0,220),games,author:'you',art:byGame(games[0]).art,saves:0,tag:'YOUR PERSONAL EDIT'};if(existing)Object.assign(existing,obj);else S.collections.unshift(obj);persist();closeModal();if(location.hash==='#collection/'+id)render();else location.hash='collection/'+id;toast(existing?'Collection updated.':'Your collection is ready. Make it travel.');}
    if(f.id==='review-form'){const [type,target]=String(fd.get('target')||'').split(':'),n=Number(fd.get('rating')),title=String(fd.get('title')||'').trim(),body=String(fd.get('body')||'').trim();if(!((type==='game'&&byGame(target))||(type==='platform'&&byPlatform(target)))||!Number.isInteger(n)||n<1||n>5){$('.form-error',f).textContent='Choose a pick and rate your experience.';return;}if(title.length<5||title.length>90||body.length<20||body.length>1800){$('.form-error',f).textContent='Add a headline of 5–90 characters and a review of 20–1,800 characters.';return;}S.reviews.unshift({id:'review-'+Date.now().toString(36),type,target,rating:n,title,body,author:'you',helpful:0,date:new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})});persist();closeModal();if(route===type&&routeId===target){render();$('#reviews')?.scrollIntoView({block:'start'});}else{location.hash=type+'/'+target;setTimeout(()=>$('#reviews')?.scrollIntoView({block:'start'}),100);}toast('Your perspective is published on this device.');}
    if(f.id==='profile-form'){const name=String(fd.get('name')||'').trim();if(name.length<2||name.length>40){$('.form-error',f).textContent='Use a name between 2 and 40 characters.';return;}S.profile={name,bio:String(fd.get('bio')||'').trim().slice(0,160)};persist();closeModal();render();toast('Profile updated.');}
  });
  let searchTimer;document.addEventListener('input',e=>{const id=e.target.id;if(id!=='catalog-search'&&id!=='platform-search')return;clearTimeout(searchTimer);const value=e.target.value,position=e.target.selectionStart;searchTimer=setTimeout(()=>{if(id==='catalog-search')query=value.slice(0,150);else platformQuery=value.slice(0,150);const y=window.scrollY;render();const el=$('#'+id);el?.focus({preventScroll:true});try{el?.setSelectionRange(position,position);}catch{}window.scrollTo(0,y);},160);});
  document.addEventListener('change',e=>{if(e.target.id==='game-sort'){sort=e.target.value;refreshKeepFocus();}if(e.target.id==='platform-sort'){platformSort=e.target.value;refreshKeepFocus();}});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#global-search input').focus();}});
  const scrollPositions={};let currentHash=location.hash;window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);scrollPositions[currentHash]=window.scrollY;currentHash=location.hash;if($('#modal').open)closeModal();render();window.scrollTo(0,scrollPositions[currentHash]||0);$('#main').focus({preventScroll:true});});
  render();
  if(!storageOK)setTimeout(()=>toast('Browser storage is unavailable. Changes will last for this session.'),1000);
  if(document.modelContext?.registerTool){const ac=new AbortController();window.addEventListener('pagehide',()=>ac.abort(),{once:true});const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:ac.signal})).catch(()=>{});}catch{}};register({name:'search_degenbot_catalog',title:'Search DegenBot catalog',description:'Read fictional offline game and platform records matching a search. Does not change state.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string')throw Error('query must be a string');const q=input.query.trim().toLowerCase();return {games:D.games.filter(g=>(g.name+' '+g.studio+' '+g.category).toLowerCase().includes(q)).map(({id,name,category})=>({id,name,category})),platforms:D.platforms.filter(p=>p.name.toLowerCase().includes(q)).map(({id,name})=>({id,name}))};}});register({name:'save_degenbot_games',title:'Save games to local picks',description:'Save valid games in the offline local profile and update the visible interface.',inputSchema:{type:'object',properties:{gameIds:{type:'array',items:{type:'string'}}},required:['gameIds'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.gameIds)||input.gameIds.some(id=>typeof id!=='string'||!byGame(id)))throw Error('Every game ID must exist');S.savedGames=[...new Set([...S.savedGames,...input.gameIds])];persist();render();return {savedGameIds:[...S.savedGames],storage:storageOK?'local':'session'};}});}
})();
